function loadState(){
 try{
  const raw=localStorage.getItem('vidoV10FinalState');
  const parsed=raw?JSON.parse(raw):null;
  if(!parsed||typeof parsed!=='object')return {...DEFAULT_STATE,history:['home']};
  const merged={...DEFAULT_STATE,...parsed};
  merged.notes=Array.isArray(merged.notes)?merged.notes:[];
  merged.mistakes=Array.isArray(merged.mistakes)?merged.mistakes:[];
  merged.history=Array.isArray(merged.history)&&merged.history.length?merged.history.filter(x=>['home','topics','path','learn','search','notes','mistakes','videos','progress','glossary','help','ihk','sim'].includes(x)):['home'];
  merged.answers=merged.answers&&typeof merged.answers==='object'?merged.answers:{};
  merged.hints=merged.hints&&typeof merged.hints==='object'?merged.hints:{};
  merged.learningTopic=typeof merged.learningTopic==='string'?merged.learningTopic:'all';
  merged.mastery=merged.mastery&&typeof merged.mastery==='object'?merged.mastery:{};
  merged.daily=merged.daily&&typeof merged.daily==='object'?merged.daily:{date:'',progress:0,target:10};
  merged.daily.target=10;
  merged.current=Number.isInteger(merged.current)&&merged.current>=0&&merged.current<Q.length?merged.current:0;
  merged.lastRoute=merged.history.includes(merged.lastRoute)?merged.lastRoute:'home';
  return merged;
 }catch{return {...DEFAULT_STATE,history:['home']};}
}
