function search(){const raw=$('searchInput').value.trim().replace(/^#/,'');const res=Q.filter(q=>q.id===raw);$('searchResults').innerHTML=res.length?res.map(q=>`<div class="row"><div><b>#${q.id} · ${qSkill(q)}</b><div class="rowSub"><span class="ltr">${q.ip}</span> · ${levelLabel(q.level)}</div></div><button class="primary" data-open="${q.id}">${t('open')}</button></div>`).join(''):`<div class="empty">${t('no_question')}</div>`;$('searchResults').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openQuestion(b.dataset.open))}
$('searchBtn').onclick=search;$('searchInput').onkeydown=e=>{if(e.key==='Enter')search()};
